/**
 * Guides 详情页模板（/guides/<slug>/）
 *
 * 由 `gatsby-node.js` 的 `createPages` 从 `src/data/guides.js` 生成。
 * 为什么走模板：一篇 guide 的结构完全相同，差异全在数据；写成 N 个手写文件
 * 改一次版式就要改 N 处，必然漂移。
 *
 * 🔴 **`scope` 字段不能被省略渲染**。它是 `mk-scope` 提示条，用来把
 *    「这条能力只在短信通道成立」写在页面上。BSP 文案稿 §6 的三条禁令里，
 *    两条都是「把短信独有的能力写成了三通道通用」—— 这个字段就是那道闸门。
 *    **删它之前先回去读 §6。**
 *
 * 🔴 `softwareApp={false}`：本页不属于 Whaleal Cart 这个 Shopify 应用。
 *
 * @author 恒哥
 * @since 2026-10-12
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import { GUIDES } from '../data/guides';
import { DOCS_URL } from '../constants/brand';
import '../styles/marketing.css';

function Section({ section }) {
  return (
    <section className="mk-section">
      <h2>{section.h}</h2>
      {section.p &&
        section.p.map((para, i) => (
          <p className="mk-section-lead" key={i}>
            {para}
          </p>
        ))}
      {section.table && (
        <table className="mk-table">
          <thead>
            <tr>
              {section.table.head.map((h) => (
                <th key={h}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {section.table.rows.map((row) => (
              <tr key={row[0]}>
                {row.map((cell, i) => (
                  <td key={i}>{i === 0 ? <strong>{cell}</strong> : cell}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      )}
      {section.p2 &&
        section.p2.map((para, i) => (
          <p className="mk-section-lead" key={i}>
            {para}
          </p>
        ))}
      {section.list && (
        <ul className="mk-list">
          {section.list.map((item) => (
            <li key={item}>{item}</li>
          ))}
        </ul>
      )}
      {section.scope && (
        <div className="mk-scope">
          <strong>Scope.</strong> {section.scope}
        </div>
      )}
    </section>
  );
}

export default function GuideTemplate({ pageContext }) {
  const { guide } = pageContext;
  const others = GUIDES.filter((g) => g.slug !== guide.slug);

  return (
    <Layout>
      <SEO
        title={guide.title}
        description={guide.excerpt}
        pathname={`/guides/${guide.slug}/`}
        softwareApp={false}
        ogType="article"
        breadcrumbs={[
          { name: 'Home', path: '/' },
          { name: 'Guides', path: '/guides/' },
          { name: guide.title, path: `/guides/${guide.slug}/` },
        ]}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow">{guide.subtitle}</span>
          <h1>{guide.title}</h1>
          <p className="mk-lead">{guide.excerpt}</p>
          <p className="mk-meta">
            {guide.readMinutes} min read · updated {guide.updated}
          </p>
        </header>

        {guide.sections.map((section) => (
          <Section section={section} key={section.h} />
        ))}

        <section className="mk-section">
          <h2>Keep reading</h2>
          <div className="mk-grid">
            {others.map((g) => (
              <article className="mk-card" key={g.slug}>
                <h3>{g.title}</h3>
                <p>{g.excerpt}</p>
                <Link className="mk-card-link" to={`/guides/${g.slug}/`}>
                  Read the guide &rarr;
                </Link>
              </article>
            ))}
          </div>
          <div className="mk-actions">
            <Link className="mk-btn mk-btn-secondary" to="/guides/">
              All guides
            </Link>
            <a className="mk-btn mk-btn-secondary" href={DOCS_URL} target="_blank" rel="noopener noreferrer">
              Technical docs
            </a>
          </div>
        </section>
      </div>
    </Layout>
  );
}
